const integer=(value,min,max,name)=>{if(!/^\d+$/.test(String(value)))throw new Error(`${name}必须是整数`);const n=Number(value);if(!Number.isSafeInteger(n)||n<min||n>max)throw new Error(`${name}应在${min}～${max}范围内`);return n;};
const decimal=(value,min,max,name)=>{if(String(value).trim()==='')throw new Error(`${name}不能为空`);const n=Number(value);if(!Number.isFinite(n)||n<min||n>max)throw new Error(`${name}应在${min}～${max}范围内`);return n;};
const ipString=n=>[24,16,8,0].map(s=>(n>>>s)&255).join('.');
export function subnet(ip,prefix){const parts=String(ip).split('.');if(parts.length!==4)throw new Error('请输入4段IPv4地址，例如192.168.10.130');const octets=parts.map(p=>integer(p,0,255,'地址段'));const p=integer(prefix,0,32,'前缀长度');const n=octets.reduce((a,v)=>a*256+v,0)>>>0,mask=p===0?0:(0xffffffff<<(32-p))>>>0,network=(n&mask)>>>0,end=(network|(~mask>>>0))>>>0,total=2**(32-p);const standard=p<31;return{prefix:p,mask:ipString(mask),network:ipString(network),broadcast:standard?ipString(end):'不采用常规广播地址',first:ipString(standard?network+1:network),last:ipString(standard?end-1:end),total,usable:standard?total-2:total,binary:octets.map(v=>v.toString(2).padStart(8,'0')).join('.'),note:p===31?'/31按点对点使用解释，两个地址可用于端点。':p===32?'/32表示单个主机地址。':'按传统广播子网计算，排除网络与广播地址。'};}
export function tcpAck(seq,payload,syn=false,fin=false){const n=integer(seq,0,4294967295,'序列号'),bytes=integer(payload,0,4294967295,'数据字节数');const used=bytes+Number(syn)+Number(fin);return{ack:(n+used)%4294967296,used,formula:`(${n} + ${bytes} + ${Number(syn)} + ${Number(fin)}) mod 2³²`,note:'假设此段与此前数据连续接收、没有缺口；不模拟乱序、SACK或重传。'};}
export function delays(bytes,mbps,km,velocity){const b=integer(bytes,1,1e12,'分组字节数'),rate=decimal(mbps,.000001,1e9,'链路速率'),distance=decimal(km,0,1e9,'距离'),v=decimal(velocity,1,3e8,'传播速度');const transmission=b*8/(rate*1e6)*1000,propagation=distance*1000/v*1000,bdp=rate*1e6*(2*propagation/1000)/8;return{transmission,propagation,total:transmission+propagation,bdp,note:'单链路、忽略排队和处理；BDP使用仅由传播时延估计的RTT=2×单程传播时延。'};}
export function mss(mtu,ipVersion,tcpHeader){const m=integer(mtu,68,1000000,'MTU'),header=integer(tcpHeader,20,60,'TCP首部长度');if(header%4)throw new Error('TCP首部长度需为4字节的倍数');if(!['4','6'].includes(String(ipVersion)))throw new Error('IP版本应为4或6');const ip=String(ipVersion)==='6'?40:20;if(m<=ip+header)throw new Error('MTU必须大于IP与TCP首部之和');return{ipHeader:ip,tcpHeader:header,mss:m-ip-header,note:'使用无IP选项/扩展首部且无隧道额外开销的简化模型；实际受路径MTU与协商等约束。'};}
export function fragment(payload,mtu,header=20){const h=integer(header,20,60,'IPv4首部长度');if(h%4)throw new Error('IPv4首部长度需为4字节的倍数');const b=integer(payload,1,65535-h,'原始IP载荷'),m=integer(mtu,h+8,65535,'MTU');const chunk=Math.floor((m-h)/8)*8,result=[];let offset=0;while(offset<b){const remaining=b-offset,size=remaining<=m-h?remaining:chunk;result.push({number:result.length+1,payload:size,total:size+h,offset:offset/8,mf:offset+size<b?1:0});offset+=size;}return result;}
